"""Authored component boundaries in the original 418 px action drawings.

Part coordinates describe visible anatomy/props, never a full-frame billboard.
Depths and hidden surfaces are inferred; front contours/colour come from art.
"""

def rect(x0,y0,x1,y1):return [(x0,y0),(x1,y0),(x1,y1),(x0,y1)]


def part(name,points,kind='skin',front=-40,depth=36,parent='spine',**extra):
    return dict(name=name,points=points,kind=kind,front=front,depth=depth,parent=parent,**extra)


def config(title,head,face,eyes,mouth,parts,**extra):
    return dict(title=title,head=head,face=face,eyes=eyes,mouth=mouth,parts=parts,**extra)


